    Source: packages/compose-gen/specs/organisms/product-card.json
    A product as a card: picture, optional badge, category, name, rating, summary, price (and the old price struck through when `compareAt` is higher) and an add button. Axes: layout (vertical, horizontal), media (image, none), ratio, rating (show, hide), action (button, none), density.
    Props (p): product, labels, badges, layout, media, ratio, rating, action, density. *}
{var $v_product = ($p['product'] ?? null)}
{var $v_labels = ($p['labels'] ?? null)}
{var $v_badges = ($p['badges'] ?? null)}
{var $v_layout = ($p['layout'] ?? 'vertical')}
{var $v_media = ($p['media'] ?? 'image')}
{var $v_ratio = ($p['ratio'] ?? '4/3')}
{var $v_rating = ($p['rating'] ?? 'show')}
{var $v_action = ($p['action'] ?? 'button')}
{var $v_density = ($p['density'] ?? 'default')}
{capture $c_16}
