    {capture $c_2}
      {=og_include('blocks/media-frame.latte', ['p' => ['alt' => og_get($v_product, ['name']), 'src' => og_get($v_product, ['image']), 'ratio' => $v_ratio, 'className' => og_cnv(['h-full'])]])|noescape}
      {if og_t(og_get($v_product, ['badge']))}
        {capture $c_1}
          {=og_text(og_at($v_badges, og_get($v_product, ['badge'])))}
        {/capture}
        {=og_include('compose/Badge.latte', ['variant' => 'default', 'size' => 'default', 'class' => 'absolute left-4 top-4', 'children' => (string) $c_1])|noescape}
      {/if}
    {/capture}
    {=og_include('compose/Box.latte', ['class' => og_s(og_cnv(['relative shrink-0', (og_t(og_eq($v_layout, 'horizontal')) ? 'sm:w-48' : '')])), 'children' => (string) $c_2])|noescape}
  {/if}
  {capture $c_15}
    {capture $c_3}
      {=og_text(og_get($v_product, ['category']))}
    {/capture}
    {=og_include('compose/Text.latte', ['size' => 'xs', 'class' => 'uppercase tracking-wide text-muted-foreground', 'children' => (string) $c_3])|noescape}
    {capture $c_5}
      {if og_t(og_get($v_product, ['href']))}
        {capture $c_4}
          {=og_text(og_get($v_product, ['name']))}
        {/capture}
        {=og_include('compose/Link.latte', ['href' => og_url(og_s(og_get($v_product, ['href']))), 'variant' => 'default', 'attrs' => og_attrs(['data-slot', 'open']), 'children' => (string) $c_4])|noescape}
      {else}
        {=og_text(og_get($v_product, ['name']))}
      {/if}
    {/capture}
    {=og_include('compose/Title.latte', ['as' => 3, 'size' => 'base', 'weight' => 'bold', 'children' => (string) $c_5])|noescape}
    {if og_t(og_eq($v_rating, 'show'))}
      {capture $c_7}
        {=og_include('blocks/rating.latte', ['p' => ['value' => og_get($v_product, ['rating']), 'label' => og_tpl(og_get($v_labels, ['ratingLabel']), [og_get($v_product, ['rating'])])]])|noescape}
        {capture $c_6}
          {=og_text(og_tpl(og_get($v_labels, ['reviews']), [og_get($v_product, ['reviews'])]))}
        {/capture}
        {=og_include('compose/Text.latte', ['size' => 'xs', 'class' => 'text-muted-foreground', 'children' => (string) $c_6])|noescape}
      {/capture}
      {=og_include('compose/Group.latte', ['gap' => '2', 'children' => (string) $c_7])|noescape}
    {/if}
    {if og_t(og_eq($v_density, 'default'))}
      {capture $c_8}
        {=og_text(og_get($v_product, ['summary']))}
      {/capture}
      {=og_include('compose/Text.latte', ['size' => 'sm', 'class' => 'text-muted-foreground', 'children' => (string) $c_8])|noescape}
    {/if}
    {capture $c_14}
      {capture $c_12}
        {capture $c_9}
          {=og_text(og_money(og_get($v_product, ['price']), og_get($v_product, ['currency'])))}
        {/capture}
        {=og_include('compose/Text.latte', ['size' => 'xl', 'weight' => 'bold', 'children' => (string) $c_9])|noescape}
        {if og_t(og_and([og_get($v_product, ['compareAt']), og_gt(og_get($v_product, ['compareAt']), og_get($v_product, ['price']))]))}
          {capture $c_11}
            {capture $c_10}
              {=og_text(og_get($v_labels, ['was']))}
            {/capture}
            {=og_include('compose/Inline.latte', ['class' => 'sr-only', 'children' => (string) $c_10])|noescape}
            {=og_text(og_money(og_get($v_product, ['compareAt']), og_get($v_product, ['currency'])))}
          {/capture}
          {=og_include('compose/Text.latte', ['tag' => 'del', 'size' => 'sm', 'class' => 'relative text-muted-foreground', 'attrs' => og_attrs(['data-slot', 'compare-at']), 'children' => (string) $c_11])|noescape}
        {/if}
      {/capture}
      {=og_include('compose/Group.latte', ['gap' => '2', 'align' => 'baseline', 'class' => 'flex-wrap', 'children' => (string) $c_12])|noescape}
      {if og_t(og_eq($v_action, 'button'))}
        {capture $c_13}
          {=og_text((og_t(og_get($v_product, ['inStock'])) ? og_get($v_labels, ['add']) : og_get($v_labels, ['soldOut'])))}
        {/capture}
        {=og_include('compose/Button.latte', ['variant' => og_s((og_t(og_get($v_product, ['inStock'])) ? 'default' : 'outline')), 'size' => 'sm', 'disabled' => og_t(!(og_t(og_get($v_product, ['inStock'])))), 'children' => (string) $c_13])|noescape}
      {/if}
    {/capture}
    {=og_include('compose/Group.latte', ['gap' => '4', 'justify' => 'between', 'class' => 'mt-auto pt-2', 'children' => (string) $c_14])|noescape}
  {/capture}
  {=og_include('compose/CardContent.latte', ['class' => 'flex flex-1 flex-col gap-2', 'children' => (string) $c_15])|noescape}
{/capture}
{=og_include('compose/Block.latte', ['tag' => 'article', 'class' => og_s(og_cnv(['flex flex-col gap-8 bg-card p-6 text-card-foreground inset-ring inset-ring-border rounded', 'h-full gap-4 overflow-hidden', (og_t(og_eq($v_layout, 'horizontal')) ? 'flex flex-col sm:flex-row' : 'flex flex-col')])), 'attrs' => og_attrs(['data-slot', 'card', 'data-layout', $v_layout]), 'children' => (string) $c_16])|noescape}
